-- Auto-generated "Project folder (auto)" README rows were only UX anchors; not required
-- for sync, Jobber, or Hub Files. Safe to remove. Orphan R2 objects under
-- job-files/.../other|design/.../README.txt can be deleted manually in the bucket if desired.
DELETE FROM job_files
WHERE title = 'Project folder (auto)'
  AND filename = 'README.txt';
